CREATE TABLE IF NOT EXISTS project_activity (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,actor_type ENUM('admin','client','system') NOT NULL DEFAULT 'system',actor_id BIGINT UNSIGNED NULL,activity_type VARCHAR(80) NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NULL,metadata JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_activity_project_created(project_id,created_at),CONSTRAINT fk_activity_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_portal_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_used_at DATETIME NULL,INDEX idx_portal_client(client_id),INDEX idx_portal_expiry(expires_at),CONSTRAINT fk_portal_session_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
